package android.speech; import android.content.*; public class SpeechRecognizer {public static final int ERROR_LANGUAGE_UNAVAILABLE=13,ERROR_LANGUAGE_NOT_SUPPORTED=12,ERROR_INSUFFICIENT_PERMISSIONS=9,ERROR_NO_MATCH=7,ERROR_SPEECH_TIMEOUT=6;public static final String RESULTS_RECOGNITION="results";public static boolean available=true;public static SpeechRecognizer last;public RecognitionListener listener;public boolean canceled,destroyed;public static boolean isOnDeviceRecognitionAvailable(Context c){return available;}public static SpeechRecognizer createOnDeviceSpeechRecognizer(Context c){return last=new SpeechRecognizer();}public void setRecognitionListener(RecognitionListener l){listener=l;}public void startListening(Intent i){}public void cancel(){canceled=true;}public void destroy(){destroyed=true;}}
